package com.lupefit.feature.ejercicio.ui;
import android.view.*; import androidx.annotation.NonNull; import androidx.recyclerview.widget.RecyclerView; import com.lupefit.core.domain.model.WorkoutSummary; import com.lupefit.feature.ejercicio.databinding.ItemRecentWorkoutBinding; import java.util.*;
public final class RecentWorkoutAdapter extends RecyclerView.Adapter<RecentWorkoutAdapter.Holder>{ private final List<WorkoutSummary> items=new ArrayList<>(); public void submitList(List<WorkoutSummary> v){items.clear();if(v!=null)items.addAll(v);notifyDataSetChanged();} @NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(ItemRecentWorkoutBinding.inflate(LayoutInflater.from(p.getContext()),p,false));} public void onBindViewHolder(@NonNull Holder h,int p){h.bind(items.get(p));} public int getItemCount(){return items.size();} static final class Holder extends RecyclerView.ViewHolder{final ItemRecentWorkoutBinding b;Holder(ItemRecentWorkoutBinding b){super(b.getRoot());this.b=b;}void bind(WorkoutSummary s){b.tvWorkoutName.setText(s.getName());b.tvWorkoutDetails.setText(String.format(Locale.getDefault(),"%s • %d min • %d kcal",s.getType(),s.getDurationMinutes(),s.getCalories()));}}}
